@extends('layout') @section('content')<div class="actions"><h1>Invitations</h1><a href="{{ route('invitations.create') }}">Invite user</a></div><table><tr><th>Email</th><th>Company</th><th>Role</th><th>Expires</th><th>Status</th><th>Action</th></tr>@forelse($invitations as $i)<tr><td>{{ $i->email }}</td><td>{{ $i->company->name }}</td><td>{{ $i->role }}</td><td>{{ $i->expires_at->format('Y-m-d H:i') }}</td><td>{{ $i->accepted_at ? 'Accepted' : ($i->revoked_at ? 'Revoked' : ($i->expires_at->isPast() ? 'Expired' : 'Pending')) }}</td><td>@if(!$i->accepted_at && !$i->revoked_at && !$i->expires_at->isPast())<form method="post" action="{{ route('invitations.revoke', $i->id) }}">@csrf<button>Revoke</button></form>@endif</td></tr>@empty<tr><td colspan="6">No invitations.</td></tr>@endforelse</table>{{ $invitations->links() }}@endsection